style:
/* 砚山 —— 新中式水墨：宣纸、淡墨远山、一校旧印。全卷只有墨与灰褐，红只出现在印章与题点。 */
.tw-cosolar--yanshan.resume-paper {
  background: #f9f7f1;
  color: #33312c;
}

.tw-cosolar--yanshan.resume-paper .paper-header {
  /* center 骨架的页眉自带一块青色几何底，这里必须显式盖回宣纸色 */
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  grid-template-rows: auto auto auto;
  margin: 0 calc(var(--paper-mr, 15mm) * -1) 9mm calc(var(--paper-ml, 15mm) * -1);
  padding: 9mm 15mm 3mm;
  border-bottom: none;
  background: #f9f7f1;
  text-align: left;
}

/* 一重淡墨远山，像纸面晕开的一道痕 */
/* 顶部装饰：原先是灰绿色的山脊斜带，改成模板主题色的横条 */
.tw-cosolar--yanshan.resume-paper .paper-header::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 1.5mm;
  background: #8c4a3f;
  pointer-events: none;
  print-color-adjust: exact;
}

.tw-cosolar--yanshan.resume-paper .paper-header__crest {
  position: absolute;
  left: 15mm;
  top: 9mm;
  z-index: 1;
  margin: 0;
}

.tw-cosolar--yanshan.resume-paper .paper-header__main {
  display: contents;
}

.tw-cosolar--yanshan.resume-paper .paper-photo--crest {
  /* 一寸照比例：宽 22mm 对应高 22 × 35 / 25 = 30.8mm */
  width: 22mm;
  height: 30.8mm;
  border: 0.8mm solid #fff;
  border-radius: 0.6mm;
  box-shadow: 0 0 0 0.3mm rgba(90, 100, 105, 0.22);
}

.tw-cosolar--yanshan.resume-paper .paper-monogram {
  display: grid;
  place-items: center;
  /* 与证件照同一尺寸（一寸照比例 25:35），有无照片时页眉高度一致 */
  width: 22mm;
  height: 30.8mm;
  margin: 0;
  border: 0.8mm solid #fff;
  border-radius: 0.6mm;
  background: #efede5;
  color: #6f6a5e;
  font-family: var(--serif);
  font-size: calc(var(--paper-base-size) * 1.8);
  font-weight: 700;
  print-color-adjust: exact;
}

.tw-cosolar--yanshan.resume-paper .paper-name-row {
  position: relative;
  z-index: 1;
  grid-column: 1;
  grid-row: 1;
  justify-content: flex-start;
  align-items: baseline;
  gap: 3.6mm;
  padding-left: 29mm;
}

.tw-cosolar--yanshan.resume-paper .paper-name {
  color: #2d2b27;
  font-family: var(--serif);
  font-size: calc(var(--paper-base-size) * 2.5);
  letter-spacing: 0.24em;
  text-indent: 0.24em;
  line-height: 1.1;
}

/* 姓名右侧一枚旧印泥小章：全卷唯一的红 */
.tw-cosolar--yanshan.resume-paper .paper-name::after {
  content: "";
  display: inline-block;
  width: 4mm;
  height: 4mm;
  margin-left: 3.4mm;
  border-radius: 0.6mm;
  background: #a8443a;
  box-shadow: inset 0 0 0 0.5mm rgba(249, 247, 241, 0.85);
  vertical-align: 1.3mm;
  opacity: 0.92;
  print-color-adjust: exact;
}

.tw-cosolar--yanshan.resume-paper .paper-identity {
  padding: 0;
  border: none;
  background: none;
  color: #8b8578;
  font-size: calc(var(--paper-base-size) * 0.82);
  letter-spacing: 0.14em;
}

.tw-cosolar--yanshan.resume-paper .paper-role {
  position: relative;
  z-index: 1;
  grid-column: 1;
  grid-row: 2;
  margin-top: 1.6mm;
  padding-left: 29mm;
  color: #6f6a5e;
  font-weight: 400;
  letter-spacing: 0.18em;
}

.tw-cosolar--yanshan.resume-paper .paper-contacts {
  position: relative;
  z-index: 1;
  grid-column: 1 / -1;
  grid-row: 3;
  /* 证件照是一寸照比例、比原来高 8.8mm，联系方式要多让出这段才不会被压住 */
  margin-top: 16mm;
  color: #5d5950;
}

.tw-cosolar--yanshan.resume-paper .paper-contact + .paper-contact::before {
  color: #b5afa2;
}

/* center 骨架给 line 标题硬编码了青色与学位帽图标，这里以同特异度压回墨色、藏起图标 */
.tw-cosolar--yanshan.resume-paper .paper-style-line .paper-section__title {
  color: #2d2b27;
}

.tw-cosolar--yanshan.resume-paper .paper-style-line .paper-section__icon {
  display: none;
}

/* 分区标题：宋体墨字压一条淡墨线，行首一枚小方点呼应印章 */
.tw-cosolar--yanshan.resume-paper .paper-section__title {
  display: flex;
  align-items: center;
  gap: 2.8mm;
  margin-bottom: 3.2mm;
  padding-bottom: 1.4mm;
  border-bottom: 1px solid rgba(51, 49, 44, 0.16);
  color: #2d2b27;
  font-family: var(--serif);
  font-size: calc(var(--paper-base-size) * 1.22);
  letter-spacing: 0.18em;
}

.tw-cosolar--yanshan.resume-paper .paper-section__title::before {
  content: "";
  flex: none;
  width: 2.2mm;
  height: 2.2mm;
  background: #a8443a;
  opacity: 0.85;
  print-color-adjust: exact;
}

.tw-cosolar--yanshan.resume-paper .paper-item-title {
  color: #2d2b27;
  font-family: var(--serif);
  font-weight: 700;
}

.tw-cosolar--yanshan.resume-paper .paper-item-period {
  color: #8b8578;
  font-variant-numeric: tabular-nums;
}

.tw-cosolar--yanshan.resume-paper .paper-item-sub {
  color: #6f6a5e;
}

.tw-cosolar--yanshan.resume-paper .paper-rich li::marker {
  color: var(--list-color, rgba(51, 49, 44, 0.45));
}

.tw-cosolar--yanshan.resume-paper .paper-note__tag {
  color: #2d2b27;
  font-weight: 600;
}

.tw-cosolar--yanshan.resume-paper .paper-footer {
  border-top: 1px solid rgba(51, 49, 44, 0.16);
  color: #9c968a;
}

/* 显式选择的列表样式接管模板默认圆点装饰，避免 data-list 被模板 ul/li 规则盖掉。 */
.tw-cosolar--yanshan.resume-paper .paper-rich ul[data-list],
.tw-cosolar--yanshan.resume-paper .paper-rich ol[data-list] {
  margin: 0.5mm 0 0;
  padding-left: 1.2em;
}
.tw-cosolar--yanshan.resume-paper .paper-rich ul[data-list] > li,
.tw-cosolar--yanshan.resume-paper .paper-rich ol[data-list] > li {
  padding-left: 0;
  position: relative;
}
.tw-cosolar--yanshan.resume-paper .paper-rich ul[data-list] > li::before,
.tw-cosolar--yanshan.resume-paper .paper-rich ol[data-list] > li::before {
  content: none;
  width: auto;
  height: auto;
  border-radius: 0;
  background: none;
  border: 0;
  box-shadow: none;
  left: auto;
  right: auto;
  top: auto;
  margin: 0;
  padding: 0;
}
.tw-cosolar--yanshan.resume-paper .paper-rich ul[data-list="disc"] { list-style-type: disc; }
.tw-cosolar--yanshan.resume-paper .paper-rich ul[data-list="circle"] { list-style-type: circle; }
.tw-cosolar--yanshan.resume-paper .paper-rich ul[data-list="square"] { list-style-type: square; }
.tw-cosolar--yanshan.resume-paper .paper-rich ul[data-list="square-open"] { list-style-type: "□   "; }
.tw-cosolar--yanshan.resume-paper .paper-rich ul[data-list="square-open"] > li::marker { font-size: 0.62em; }
.tw-cosolar--yanshan.resume-paper .paper-rich ul[data-list="diamond"] { list-style-type: "◆   "; }
.tw-cosolar--yanshan.resume-paper .paper-rich ul[data-list="diamond-open"] { list-style-type: "◇   "; }
.tw-cosolar--yanshan.resume-paper .paper-rich ul[data-list="diamond"] > li::marker,
.tw-cosolar--yanshan.resume-paper .paper-rich ul[data-list="diamond-open"] > li::marker { font-size: 0.62em; }
.tw-cosolar--yanshan.resume-paper .paper-rich ul[data-list="triangle"] { list-style-type: "▸   "; }
.tw-cosolar--yanshan.resume-paper .paper-rich ul[data-list="check"] { list-style-type: "✓   "; }
.tw-cosolar--yanshan.resume-paper .paper-rich ul[data-list="check"] > li::marker { font-size: 0.75em; }
.tw-cosolar--yanshan.resume-paper .paper-rich ol[data-list="decimal"] { list-style-type: decimal; }
.tw-cosolar--yanshan.resume-paper .paper-rich ol[data-list="cjk"] { list-style-type: miniwho-cjk; }
.tw-cosolar--yanshan.resume-paper .paper-rich ol[data-list="roman-upper"] { list-style-type: upper-roman; }
.tw-cosolar--yanshan.resume-paper .paper-rich ol[data-list="roman-lower"] { list-style-type: lower-roman; }
.tw-cosolar--yanshan.resume-paper .paper-rich ol[data-list="alpha-upper"] { list-style-type: upper-alpha; }
.tw-cosolar--yanshan.resume-paper .paper-rich ol[data-list="alpha-lower"] { list-style-type: lower-alpha; }
.tw-cosolar--yanshan.resume-paper .paper-rich ol[data-list="paren"] { padding-left: 1.2em; list-style: none; counter-reset: paren-item; }
.tw-cosolar--yanshan.resume-paper .paper-rich ol[data-list="paren"] > li { position: relative; counter-increment: paren-item; }
.tw-cosolar--yanshan.resume-paper .paper-rich ol[data-list="paren"] > li::before {
  content: "（" counter(paren-item) "）";
  position: absolute;
  right: calc(100% + 0.08em);
  top: 0;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  font-size: 0.62em;
  line-height: 1.7;
  white-space: nowrap;
}
.tw-cosolar--yanshan.resume-paper .paper-rich ol[data-list="paren-right"] { padding-left: 1.2em; list-style: none; counter-reset: paren-right-item; }
.tw-cosolar--yanshan.resume-paper .paper-rich ol[data-list="paren-right"] > li { position: relative; counter-increment: paren-right-item; }
.tw-cosolar--yanshan.resume-paper .paper-rich ol[data-list="paren-right"] > li::before {
  content: counter(paren-right-item) ")";
  position: absolute;
  right: calc(100% + 0.12em);
  top: 0;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

/* 日期左栏：base 版式给的 17mm 装不下完整日期，加宽到 35mm 并禁止换行。 */
.tw-cosolar--yanshan.layout-center.resume-paper .paper-item {
  grid-template-columns: 35mm minmax(0, 1fr);
  align-items: baseline;
}

.tw-cosolar--yanshan.layout-center.resume-paper .paper-item-period {
  white-space: nowrap;
}

/* 没有日期的条目（作品集、技能等）不该再占着空的日期列，否则整体右移 */
.tw-cosolar--yanshan.resume-paper .paper-item.paper-item--undated {
  grid-template-columns: 0 minmax(0, 1fr);
  column-gap: 0;
}
